#!/usr/bin/env python3
"""Build public first-party evidence pages from the repository's implemented documentation."""
import hashlib
from html.parser import HTMLParser
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[3]
HERE = Path(__file__).resolve().parent


class Text(HTMLParser):
    def __init__(self):
        super().__init__(); self.parts=[]
    def handle_data(self, text):
        if text.strip(): self.parts.append(text.strip())


def section(text, heading):
    match = re.search(r'^## '+re.escape(heading)+r'\s*\n(.*?)(?=^## |\Z)',text,re.M|re.S)
    return match.group(1).strip() if match else ''


def main():
    desktop = (ROOT/'client/xiaoban-desktop/README.md').read_text()
