    forum = (ROOT/'services/server-forum/README.md').read_text()
    effects = (ROOT/'client/xiaoban-desktop/docs/effects.md').read_text()
    legal = {}
    for name in ['rules','privacy','terms']:
        source = (ROOT/f'services/server-forum/web/src/content/{name}.ts').read_text()
        html = re.search(r'html:\s*`(.*?)`',source,re.S).group(1)
        parser=Text();parser.feed(html);legal[name]='\n\n'.join(parser.parts)
